function bloco(linha) {
  const h = linha.match(/^(#{1,6})\s+(.*)$/);
  if (h) { const n = h[1].length; return `<h${n}>${h[2]}</h${n}>`; }
  if (/^[-*]\s+/.test(linha)) return 'ITEM:' + linha.slice(2);  // vira <li> na montagem da lista
  if (linha.trim() === '') return '';                           // separador
  return `<p>${linha}</p>`;
}

function inline(t) {
  return t
    .replace(/`([^`]+)`/g, '<code>$1</code>')       // código primeiro (zona protegida)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')  // negrito (mais específico)
    .replace(/\*(.+?)\*/g, '<em>$1</em>')             // itálico (mais geral) por último
    .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2">$1</a>');
}

function escapar(t) {
  return t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function converter(markdown) {
  const seguro = escapar(markdown);   // ESCAPA a entrada primeiro
  return seguro.split('\n').map(bloco).join('\n');  // só então formata
}
